<?php
 namespace Pterodactyl\Http\Controllers\Admin\Dezerx; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\View\View; use Prologue\Alerts\AlertsMessageBag; use Pterodactyl\Http\Controllers\Controller; use Pterodactyl\Models\Dezerx\StaffProfile; use Pterodactyl\Models\Permission; use Pterodactyl\Models\User; use Pterodactyl\Services\Dezerx\Staff\Staff; use Pterodactyl\Services\Dezerx\Staff\StaffPresets; use Pterodactyl\Services\Dezerx\Staff\StaffRecord; use Pterodactyl\Services\Dezerx\Staff\StaffRequests; class StaffController extends Controller { public function __construct(private readonly AlertsMessageBag $alert) { } public function index(): View { return view('admin.dezerx.staff.index', [ 'enabled' => Staff::enabled(), 'settings' => Staff::blob(), 'defaults' => Staff::DEFAULTS, 'presets' => StaffPresets::presets(), 'grantable' => $this->grouped(), 'labels' => StaffPresets::LABELS, 'hints' => StaffPresets::HINTS, 'never' => StaffPresets::NEVER, 'roster' => StaffRecord::roster(), 'panel' => StaffRecord::panel(), 'webhook' => Staff::hasWebhook(), 'events' => array_keys(Staff::DEFAULTS['webhook_events']), ]); } public function update(Request $request): RedirectResponse { $data = $request->validate([ 'queue_ttl_minutes' => ['required', 'integer', 'between:0,43200'], 'default_duration_minutes' => ['required', 'integer', 'between:5,43200'], 'max_duration_minutes' => ['required', 'integer', 'between:5,43200'], 'max_extensions' => ['required', 'integer', 'between:0,20'], 'extension_max_minutes' => ['required', 'integer', 'between:5,43200'], 'reminder_minutes' => ['required', 'integer', 'between:0,240'], 'max_active_per_staff' => ['required', 'integer', 'between:0,50'], 'max_staff_per_server' => ['required', 'integer', 'between:1,10'], 'max_staff_accounts' => ['required', 'integer', 'between:0,500'], 'cooldown_minutes' => ['required', 'integer', 'between:0,1440'], 'reason_min_length' => ['required', 'integer', 'between:0,200'], 'webhook_url' => ['nullable', 'string', 'max:300'], 'webhook_role_id' => ['nullable', 'string', 'max:32'], 'presets' => ['sometimes', 'array'], 'presets.*' => ['sometimes', 'array'], 'presets.*.*' => ['string', 'max:64'], ]); $events = []; foreach (array_keys(Staff::DEFAULTS['webhook_events']) as $event) { $events[$event] = $request->boolean('webhook_events.' . $event); } Staff::write([ 'enabled' => $request->boolean('enabled'), 'auto_accept_default' => $request->boolean('auto_accept_default'), 'allow_staff_requests' => $request->boolean('allow_staff_requests'), 'allow_queue' => $request->boolean('allow_queue'), 'allow_named' => $request->boolean('allow_named'), 'allow_open_ended' => $request->boolean('allow_open_ended'), 'notify_email' => $request->boolean('notify_email'), 'require_2fa' => $request->boolean('require_2fa'), 'webhook_ping_staff' => $request->boolean('webhook_ping_staff'), 'webhook_events' => $events, 'webhook_role_id' => preg_match('/^\d{5,32}$/', (string) ($data['webhook_role_id'] ?? '')) === 1 ? (string) $data['webhook_role_id'] : '', 'queue_ttl_minutes' => (int) $data['queue_ttl_minutes'], 'default_duration_minutes' => (int) $data['default_duration_minutes'], 'max_duration_minutes' => (int) $data['max_duration_minutes'], 'max_extensions' => (int) $data['max_extensions'], 'extension_max_minutes' => (int) $data['extension_max_minutes'], 'reminder_minutes' => (int) $data['reminder_minutes'], 'max_active_per_staff' => (int) $data['max_active_per_staff'], 'max_staff_per_server' => (int) $data['max_staff_per_server'], 'max_staff_accounts' => (int) $data['max_staff_accounts'], 'cooldown_minutes' => (int) $data['cooldown_minutes'], 'reason_min_length' => (int) $data['reason_min_length'], ]); StaffPresets::storePresets($data['presets'] ?? []); if ($request->filled('webhook_url')) { if (!Staff::storeWebhookUrl((string) $data['webhook_url'])) { $this->alert->danger( 'That webhook address was not saved. It has to be an https Discord webhook URL, of the shape https://discord.com/api/webhooks/000/token.' )->flash(); return redirect()->route('admin.dezerx.staff'); } } elseif ($request->boolean('webhook_clear')) { Staff::storeWebhookUrl(null); } $this->alert->success('The support staff settings have been saved.')->flash(); return redirect()->route('admin.dezerx.staff'); } public function endAll(Request $request, StaffRequests $requests): RedirectResponse { $ended = $requests->endEverything($request->user()); $this->alert->info($ended === 0 ? 'There was nothing open to end.' : $ended . ' open ' . ($ended === 1 ? 'request has' : 'requests have') . ' been ended and access taken back.')->flash(); return redirect()->route('admin.dezerx.staff'); } public function profile(Request $request, User $user): RedirectResponse { if ($user->staff !== true) { $this->alert->danger('That account is not support staff.')->flash(); return redirect()->route('admin.dezerx.staff'); } $data = $request->validate([ 'discord_id' => ['nullable', 'string', 'max:32'], 'max_active' => ['required', 'integer', 'between:1,50'], 'notes' => ['nullable', 'string', 'max:2000'], ]); $profile = $user->staffProfile ?? new StaffProfile(['user_id' => $user->id]); $profile->forceFill([ 'user_id' => $user->id, 'available' => $request->boolean('available'), 'discord_id' => preg_match('/^\d{5,32}$/', (string) ($data['discord_id'] ?? '')) === 1 ? (string) $data['discord_id'] : null, 'max_active' => (int) $data['max_active'], 'notes' => $data['notes'] ?? null, ])->saveOrFail(); $this->alert->success('Saved the details for ' . e($user->username) . '.')->flash(); return redirect()->route('admin.dezerx.staff'); } private function grouped(): array { $groups = []; foreach (Permission::permissions() as $prefix => $group) { $keys = []; foreach (array_keys($group['keys']) as $key) { $permission = $prefix . '.' . $key; if (in_array($permission, StaffPresets::NEVER, true)) { continue; } $keys[] = $permission; } if ($keys !== []) { $groups[$prefix] = $keys; } } return $groups; } } 